/* Un mock: una ventanita blanca con filas, como la captura montada a mano
   de la portada. Tipos: lista (filas con estado), kpis, cal (barras), chat. */
const mk = {
  lista: (titulo, filas) => `<div class="mk" aria-hidden="true"><div class="mk-barra"><i></i><i></i><i></i><span>${titulo}</span></div><div class="mk-cuerpo">${filas.map(([hx, nom, sub, est, cls]) => `<div class="mk-fila"><b class="hx ${hx}"></b><span>${nom}<small>${sub}</small></span><em class="${cls || ''}">${est}</em></div>`).join('')}</div></div>`,
  kpis: (titulo, kpis, filas) => `<div class="mk" aria-hidden="true"><div class="mk-barra"><i></i><i></i><i></i><span>${titulo}</span></div><div class="mk-cuerpo"><div class="mk-kpis">${kpis.map(([n, t]) => `<div><b>${n}</b><small>${t}</small></div>`).join('')}</div>${filas ? filas.map(([hx, nom, sub, est, cls]) => `<div class="mk-fila"><b class="hx ${hx}"></b><span>${nom}<small>${sub}</small></span><em class="${cls || ''}">${est}</em></div>`).join('') : ''}</div></div>`,
  cal: (titulo, filas) => `<div class="mk" aria-hidden="true"><div class="mk-barra"><i></i><i></i><i></i><span>${titulo}</span></div><div class="mk-cuerpo mk-cal"><div class="mk-dias"><span></span><span>L</span><span>M</span><span>X</span><span>J</span><span>V</span><span class="finde">S</span><span class="finde">D</span></div>${filas.map(([nom, barras]) => `<div class="mk-cfila"><span>${nom}</span>${barras.map(([d, l, c, t]) => `<i class="b ${c}" style="--d:${d};--l:${l}">${t}</i>`).join('')}</div>`).join('')}</div></div>`,
  chat: (titulo, msgs) => `<div class="mk" aria-hidden="true"><div class="mk-barra"><i></i><i></i><i></i><span>${titulo}</span></div><div class="mk-cuerpo mk-chat">${msgs.map(([quien, txt, tarjeta]) => `<div class="mk-msg ${quien === 'yo' ? 'yo' : ''}"><small>${quien === 'yo' ? 'Tú' : quien}</small><p>${txt}</p>${tarjeta ? `<div class="mk-tarjeta"><b class="hx amarillo"></b><span>${tarjeta[0]}<small>${tarjeta[1]}</small></span></div>` : ''}</div>`).join('')}</div></div>`,
};

